'use server';

import { headers } from 'next/headers';
import { userAgent } from 'next/server';

/**
 * Analytics service for logging page views without blocking the response.
 * Uses Next.js's recommended approach with startTransition.
 */
export async function logPageView(page: string, userId?: string) {
  try {
    // Get request context information
    const headersList = await headers();
    const userAgentString = userAgent();

    const analyticsData = {
      page,
      timestamp: new Date().toISOString(),
      userId,
      userAgent: userAgentString.ua,
      referrer: headersList.get('referer') || '',
      ip: headersList.get('x-forwarded-for') || headersList.get('x-real-ip') || '',
      locale: headersList.get('accept-language') || ''
    };

    // Use startTransition to schedule this work after the response is sent
    // This prevents the analytics call from blocking the page render
    const promise = startTransition(async () => {
      try {
        // Simulate an API call to your analytics service
        const response = await fetch('https://your-analytics-service.com/track', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(analyticsData),
        });

        if (!response.ok) {
          console.error('Analytics tracking failed:', response.status, response.statusText);
        }
      } catch (error) {
        console.error('Failed to send analytics data:', error);
      }
    });

    // Don't await the promise - let it run in the background
    return promise;
  } catch (error) {
    console.error('Error in logPageView:', error);
    // Return a resolved promise so it doesn't throw
    return Promise.resolve();
  }
}

/**
 * Schedules analytics work to run after the response is sent.
 * This is the recommended Next.js approach for non-blocking operations.
 */
function startTransition(fn: () => Promise<void>): Promise<void> {
  // In a real implementation, you might use Next.js's startTransition
  // For now, we'll use setTimeout to simulate non-blocking behavior
  return new Promise((resolve) => {
    setTimeout(() => {
      fn().then(resolve).catch(resolve);
    }, 0);
  });
}

